Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 566.02,
  "height": 357.0,
  "padding": 0,
  "autosize": "none",
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "ext",
      "source": "dataset",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "Y",
            "Y"
          ],
          "ops": [
            "min",
            "max"
          ],
          "as": [
            "mn",
            "mx"
          ]
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "ymax",
      "update": "max(0, length(data(''ext''))?data(''ext'')[0].mx:0)"
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "band",
      "domain": {
        "data": "dataset",
        "field": "X",
        "sort": true
      },
      "range": [
        4.5,
        562.5
      ],
      "paddingInner": 0.22599999999999998,
      "paddingOuter": 0.11299999999999999
    },
    {
      "name": "y",
      "type": "linear",
      "zero": true,
      "nice": false,
      "domain": {
        "signal": "[0, ymax*1.115]"
      },
      "range": [
        330,
        0
      ]
    },
    {
      "name": "color",
      "type": "linear",
      "domain": {
        "data": "dataset",
        "field": "Y"
      },
      "range": [
        "#f1f1f1",
        "#d9e8ed",
        "#c2e0ea",
        "#abd7e7",
        "#95cfe3",
        "#7fc7e0",
        "#6abfdd",
        "#56b8d9",
        "#42b0d6",
        "#2fa9d3",
        "#1da2d0"
      ],
      "interpolate": "rgb",
      "zero": false
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "dataset"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "X"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "y": {
            "scale": "y",
            "field": "Y"
          },
          "y2": {
            "scale": "y",
            "value": 0
          },
          "fill": {
            "scale": "color",
            "field": "Y"
          },
          "stroke": {
            "value": "#333333"
          },
          "strokeWidth": {
            "value": 1
          },
          "tooltip": {
            "signal": "{''Nr of Orders'': datum[''X''], ''Customers'': format(datum[''Y''], '','')}"
          },
          "opacity": {
            "signal": "datum.__selected__==''off''?0.25:1"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "X",
            "band": 0.5
          },
          "y": {
            "scale": "y",
            "field": "Y",
            "offset": -5
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 12.54
          },
          "fontWeight": {
            "value": 400
          },
          "fill": {
            "value": "#333333"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "text": {
            "signal": "format(datum[''Y''], '','')"
          },
          "opacity": {
            "signal": "datum.__selected__==''off''?0.25:1"
          }
        }
      },
      "from": {
        "data": "dataset"
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "X",
            "band": 0.5
          },
          "y": {
            "value": 345
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 13.467
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#000000"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "text": {
            "signal": "''''+datum[''X'']"
          }
        }
      },
      "from": {
        "data": "dataset"
      }
    }
  ]
}'
